package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.service.DashboardService;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor public class DashboardController{private final DashboardService s;@GetMapping("/summary") @PreAuthorize("hasAuthority('dashboard:read')")public ApiResponse<Map<String,Object>>summary(){return ApiResponse.ok(s.summary());}}
